const StepLabelLabelContainer = styled('span', {
  name: 'MuiStepLabel',
  slot: 'LabelContainer',
  overridesResolver: (props, styles) => styles.labelContainer,
})(({ theme }) => ({
  /* Styles applied to the container element which wraps `Typography` and `optional`. */
