const StepLabel = React.forwardRef(function StepLabel(inProps, ref) {
  const props = useThemeProps({ props: inProps, name: 'MuiStepLabel' });
  const {
    children,
    className,
    componentsProps = {},
    error = false,
    icon: iconProp,
    optional,
    StepIconComponent: StepIconComponentProp,
    StepIconProps,
    TypographyProps,
    ...other
  } = props;

  const { alternativeLabel, orientation } = React.useContext(StepperContext);
  const { active, disabled, completed, icon: iconContext } = React.useContext(StepContext);
  const icon = iconProp || iconContext;

  let StepIconComponent = StepIconComponentProp;

  if (icon && !StepIconComponent) {
    StepIconComponent = StepIcon;
  }

  const styleProps = {
    ...props,
    active,
    alternativeLabel,
    completed,
    disabled,
    error,
    orientation,
  };

  const classes = useUtilityClasses(styleProps);
  const { className: labelClassName, ...labelProps } = {
    ...componentsProps.label,
    ...TypographyProps,
  };

  return (
    <StepLabelRoot
      className={clsx(classes.root, className)}
      ref={ref}
      styleProps={styleProps}
      {...other}
    >
      {icon || StepIconComponent ? (
        <StepLabelIconContainer className={classes.iconContainer} styleProps={styleProps}>
          <StepIconComponent
            completed={completed}
            active={active}
            error={error}
            icon={icon}
            {...StepIconProps}
          />
        </StepLabelIconContainer>
      ) : null}
      <StepLabelLabelContainer className={classes.labelContainer} styleProps={styleProps}>
        {children ? (
          <StepLabelLabel
            variant="body2"
            component="span"
            display="block"
            className={clsx(classes.label, labelClassName)}
            styleProps={styleProps}
            {...labelProps}
          >
            {children}
          </StepLabelLabel>
        ) : null}
        {optional}
      </StepLabelLabelContainer>
    </StepLabelRoot>
  );
});

